H = "Hakeem Force Academy"
QS = [
(H, "On which date did Sir Syed Ahmad Khan die?", ["27 March 1898", "17 October 1898", "27 March 1900", "17 October 1817"], 0, "Sir Syed Ahmad Khan died on 27 March 1898 at Aligarh. He was born on 17 October 1817.", "He is buried in the compound of the Jama Masjid at Aligarh Muslim University.", [3062, 3063]),
(H, "What is the sum of the number of days in March and December?", ["60", "61", "62", "63"], 2, "March has 31 days and December has 31 days. So 31 + 31 = 62.", "The months with 31 days are January, March, May, July, August, October and December.", [1159]),
(H, "What is the Arabic word for 'day'?", ["Youm", "Layl", "Shahr", "Sana"], 0, "In Arabic a day is called Youm (Yawm). Layl is night, Shahr is month and Sana is year.", "Youm-e-Takbeer and Youm-e-Azadi use this Arabic word.", [3084]),
(H, "Which is the lowest point on land in Asia, about 430 metres below sea level?", ["Dead Sea shore", "Turpan Depression", "Caspian Sea shore", "Death Valley"], 0, "The shore of the Dead Sea is the lowest land elevation on Earth, about 430 metres below sea level. It lies between Jordan and Israel or the West Bank.", "Death Valley is the lowest point in North America, not Asia.", [643]),
(H, "Who demanded the separation of Sindh from the Bombay Presidency in his Fourteen Points?", ["Quaid-e-Azam Muhammad Ali Jinnah", "Allama Iqbal", "Sir Syed Ahmad Khan", "Liaquat Ali Khan"], 0, "Jinnah presented his Fourteen Points in 1929 and one of them demanded that Sindh be separated from Bombay and made a separate province.", "Sindh was actually separated from Bombay in 1936 and became a province on 1 April 1936.", [4399]),
(H, "What type of democracy does Pakistan have under the 1973 Constitution?", ["Parliamentary democracy", "Presidential democracy", "Direct democracy", "Monarchy"], 0, "The 1973 Constitution set up a federal parliamentary system. The Prime Minister heads the government and the President is the head of state.", "The Prime Minister is elected by the National Assembly.", [746]),
(H, "In which year was the Simla (Shimla) Deputation held?", ["1901", "1906", "1911", "1916"], 1, "A Muslim delegation led by Sir Aga Khan met Viceroy Lord Minto at Simla on 1 October 1906. This led to the founding of the Muslim League in December 1906.", "The deputation demanded separate electorates for Muslims.", [2350, 3675]),
(H, "In which province of Pakistan is Dera Ghazi Khan located?", ["Sindh", "Punjab", "Balochistan", "Khyber Pakhtunkhwa"], 1, "Dera Ghazi Khan is a city and division in southern Punjab, on the west bank of the Indus river.", "Dera Ismail Khan, in contrast, is in Khyber Pakhtunkhwa.", [2215]),
(H, "What is the derivative of 9 with respect to x?", ["9", "1", "0", "9x"], 2, "9 is a constant and the derivative of any constant is zero.", "The derivative of x is 1.", [1100]),
(H, "What is the derivative of -9 with respect to x?", ["-9", "0", "9", "-1"], 1, "-9 is a constant, and the derivative of a constant is always zero.", "The derivative of e to the power x is e to the power x itself.", [3090]),
(H, "How many degrees is a right angle?", ["45", "60", "90", "180"], 2, "A right angle is one quarter of a full turn of 360 degrees, which is 90 degrees.", "Two right angles make a straight angle of 180 degrees.", [1828]),
(H, "Which is the largest polar desert in the world?", ["Antarctic Desert", "Arctic Desert", "Gobi Desert", "Sahara Desert"], 0, "The Antarctic Desert covers about 14 million square kilometres and is the largest desert on Earth. It gets very little precipitation.", "The Sahara is the largest hot desert.", [3170]),
]
